        commentTokens: { line: "//" },
        indentOnInput: /^\s*(КонецЕсли|ИначеЕсли|Иначе|КонецЦикла|КонецПопытки|Исключение|КонецПроцедуры|КонецФункции|EndIf|ElsIf|Else|EndDo|EndTry|Except|EndProcedure|EndFunction)\b/i,
